def kthByBitCount(n, k):
    from math import comb

    def count_le(x, c):
        res = 0
        ones = 0
        for i in range(x.bit_length() - 1, -1, -1):
            if x >> i & 1:
                need = c - ones
                if 0 <= need <= i:
                    res += comb(i, need)
                ones += 1
        if ones == c:
            res += 1
        return res

    c = 1
    while True:
        total = count_le(n, c)
        if k <= total:
            break
        k -= total
        c += 1
    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi) // 2
        if count_le(mid, c) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
